{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "video-template-frame-bold-signal",
  "title": "Bold Signal Frame",
  "title_i18n": {
    "en": "Bold Signal Frame",
    "zh-CN": "大胆信号卡帧"
  },
  "version": "0.1.0",
  "description": "Bold colored card on a dark gradient — big section number, nav breadcrumb, orange card sliding in, title rising.",
  "description_i18n": {
    "en": "Bold colored card on a dark gradient — big section number, nav breadcrumb, orange card sliding in, title rising.",
    "zh-CN": "大胆信号卡帧:暗渐变底 + 大编号 + 导航面包屑 + 橙色卡片滑入 + 标题升起, 高冲击力"
  },
  "license": "Apache-2.0",
  "author": {
    "name": "nexu-io",
    "url": "https://github.com/nexu-io",
    "contact": "open-design@nexu.io"
  },
  "homepage": "https://github.com/nexu-io/html-video/tree/main/templates/frame-bold-signal",
  "tags": [
    "video-template",
    "first-party",
    "video",
    "hyperframes",
    "html-video",
    "motion",
    "bold",
    "card",
    "dark",
    "orange",
    "section",
    "signal",
    "high-impact",
    "presentation"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "video",
    "scenario": "video",
    "surface": "hyperframes",
    "engine": "hyperframes",
    "preview": {
      "type": "video",
      "poster": "https://cdn.jsdelivr.net/gh/nexu-io/open-design@main/plugins/_official/video-templates/frame-bold-signal/preview.png",
      "video": "https://cdn.jsdelivr.net/gh/nexu-io/open-design@main/plugins/_official/video-templates/frame-bold-signal/preview.mp4"
    },
    "useCase": {
      "query": {
        "en": "Use the Bold Signal Frame template to turn my section into a bold colored-card divider — a big section number, a nav breadcrumb, and a vibrant orange card sliding in from the right with the title rising. Preserve the template's visual signature, use real content, and avoid lorem ipsum or placeholder images.",
        "zh-CN": "用「大胆信号卡帧」模板把我的章节做成一段大胆色卡分隔:大编号 + 导航面包屑 + 鲜橙卡片从右滑入 + 标题升起。保持模板的视觉签名,使用真实内容,避免 lorem ipsum 和占位图片。"
      }
    },
    "inputs": [
      {
        "name": "aspect",
        "label": "Aspect ratio",
        "type": "select",
        "options": [
          "16:9"
        ],
        "default": "16:9"
      },
      {
        "name": "format",
        "label": "Output format",
        "type": "select",
        "options": [
          "mp4",
          "webm"
        ],
        "default": "mp4"
      },
      {
        "name": "durationSec",
        "label": "Duration (seconds)",
        "type": "number",
        "default": 15
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./template.json",
        "./source"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "compose",
          "atoms": [
            "file-write"
          ]
        },
        {
          "id": "render",
          "atoms": [
            "media-video"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write",
      "media:video-generate"
    ],
    "provenance": {
      "origin": {
        "name": "none (original preset by the L2 skill author)",
        "kind": "none",
        "reference": "No specific real-world studio; the 'Bold Signal' look is an original preset composed by the frontend-slides author"
      },
      "via_skill": {
        "name": "frontend-slides",
        "author": "Zara Zhang",
        "url": "https://github.com/zarazhangrui/frontend-slides",
        "license": "MIT",
        "source_file": "STYLE_PRESETS.md (preset \"Bold Signal\")"
      },
      "transformation": "Static slide preset → animated hyperframes timeline (section number rolls in, nav breadcrumb fades, #FF5722 focal card slides in from the right, title rises) built as original CSS keyframes. Original sample data. No upstream source code copied verbatim.\n"
    }
  }
}

